/**
 * In-system sub-regions + fast transit lanes — issue #355 (P5b).
 *
 * Pure data/logic layer over the optional `regions` + `lanes` records a
 * system definition may carry (authored in authored-systems.js, generated by
 * scripts/generate-galaxy.mjs). No THREE, no DOM, no save data:
 *
 * - Region membership is DERIVED from position at read time (regionAt) and is
 *   never persisted. The pre-P5b content disc is region 0 implicitly — it has
 *   no record and no name in data.
 * - A transit lane is a corridor volume (a capsule around the straight
 *   segment between the two lane anchors) in which the ship's existing
 *   cruise/burn envelope is multiplied by CORRIDOR_FACTOR. No new key, no
 *   SKU, no new event: the corridor is a read of position, exactly like the
 *   sun-heat keep sphere, and the multiplier decays back to 1 over ~1 s on
 *   exit (session-only module state below, keyed per ctx).
 * - The slowest hull class (freighter, burn 240 u/s) must sustain
 *   >= 500 u/s inside a lane: 240 * CORRIDOR_FACTOR(2.2) = 528 u/s, so the
 *   longest legal leg (8,000 u) reads as <= ~16 s of travel — the pins in
 *   scripts/issue-355-regions-test.mjs hold the numbers.
 *
 * Bounds (all validated by the generator and the focused suite):
 *   region centers draw at 3,500-8,000 u (x/z, float-safe ceiling);
 *   region radius 180-420 u; regions >= 500 u clear of each other and of
 *   every pre-P5b furniture position; lanes resolve endpoints from region
 *   centers at read time ('core' resolves to the station position).
 */

import { SYSTEMS, SHIP_CLASSES } from './state.js';

export const REGION_KINDS = Object.freeze(['outpost', 'field', 'wreck', 'anomaly']);
export const CORE_ANCHOR = 'core';

/** Region center radius band (x/z), the float-safe P5b ceiling. */
export const REGION_MIN_CENTER_RADIUS = 3500;
export const REGION_MAX_CENTER_RADIUS = 8000;
/** Region disc radius band. */
export const REGION_MIN_RADIUS = 180;
export const REGION_MAX_RADIUS = 420;
/** Minimum clearance between a region and any other region/furniture anchor. */
export const REGION_SEPARATION = 500;

/** Corridor capsule radius around the lane segment. */
export const CORRIDOR_RADIUS = 220;
/** Envelope multiplier inside a corridor (freighter burn 240 -> 528 u/s). */
export const CORRIDOR_FACTOR = 2.2;
/** Seconds for the multiplier to decay back to 1 after leaving a corridor. */
export const CORRIDOR_DECAY_SECONDS = 1;
/** Ramp-in rate (per second) so the boost is up in a fraction of a second. */
export const CORRIDOR_RAMP_RATE = 6;

const EMPTY = Object.freeze([]);

function fin(v) {
  return typeof v === 'number' && Number.isFinite(v);
}

/** The system's region records, or an empty list. */
export function regionsOf(def) {
  return def && Array.isArray(def.regions) ? def.regions : EMPTY;
}

/** The system's lane records, or an empty list. */
export function lanesOf(def) {
  return def && Array.isArray(def.lanes) ? def.lanes : EMPTY;
}

function regionById(def, id) {
  if (!def || typeof id !== 'string') return null;
  const regions = regionsOf(def);
  for (let i = 0; i < regions.length; i++) {
    const r = regions[i];
    if (r && r.id === id) return r;
  }
  return null;
}

/**
 * Resolve a lane endpoint id to a world anchor [x, y, z]. 'core' is the
 * station position (the implicit region-0 anchor); anything else is a
 * region id. Returns null when the id does not resolve.
 */
export function laneAnchor(def, id) {
  if (!def) return null;
  if (id === CORE_ANCHOR) {
    const p = def.station && def.station.position;
    return Array.isArray(p) && p.length === 3 && p.every(fin) ? p : null;
  }
  const region = regionById(def, id);
  const p = region && region.center;
  return Array.isArray(p) && p.length === 3 && p.every(fin) ? p : null;
}

/** Both endpoints of a lane, resolved; null when either side is unknown. */
export function lanePoints(def, lane) {
  if (!lane || typeof lane.from !== 'string' || typeof lane.to !== 'string') return null;
  const a = laneAnchor(def, lane.from);
  const b = laneAnchor(def, lane.to);
  return a && b ? { a, b } : null;
}

/** Region containing the (x, z) point, or null. Membership is derived, never persisted. */
export function regionAt(def, x, z) {
  if (!def || !fin(x) || !fin(z)) return null;
  const regions = regionsOf(def);
  for (let i = 0; i < regions.length; i++) {
    const r = regions[i];
    if (!r || !Array.isArray(r.center)) continue;
    const cx = r.center[0];
    const cz = r.center[2];
    if (!fin(cx) || !fin(cz) || !fin(r.radius)) continue;
    const dx = x - cx;
    const dz = z - cz;
    if (dx * dx + dz * dz <= r.radius * r.radius) return r;
  }
  return null;
}

/** Squared distance from point P to segment AB (3D). */
function distPointSegmentSq(px, py, pz, a, b) {
  const abx = b[0] - a[0];
  const aby = b[1] - a[1];
  const abz = b[2] - a[2];
  const apx = px - a[0];
  const apy = py - a[1];
  const apz = pz - a[2];
  const lenSq = abx * abx + aby * aby + abz * abz;
  let t = lenSq > 0 ? (apx * abx + apy * aby + apz * abz) / lenSq : 0;
  if (t < 0) t = 0;
  else if (t > 1) t = 1;
  const dx = apx - abx * t;
  const dy = apy - aby * t;
  const dz = apz - abz * t;
  return dx * dx + dy * dy + dz * dz;
}

/** The lane whose corridor volume contains the point, or null. */
export function corridorAt(def, x, y, z) {
  if (!def || !fin(x) || !fin(y) || !fin(z)) return null;
  const lanes = lanesOf(def);
  const limitSq = CORRIDOR_RADIUS * CORRIDOR_RADIUS;
  for (let i = 0; i < lanes.length; i++) {
    const pts = lanePoints(def, lanes[i]);
    if (!pts) continue;
    if (distPointSegmentSq(x, y, z, pts.a, pts.b) <= limitSq) return lanes[i];
  }
  return null;
}

/**
 * Session corridor envelope for this ctx: CORRIDOR_FACTOR inside a corridor
 * volume, easing back to 1 over ~CORRIDOR_DECAY_SECONDS on exit. Session-only
 * module state (a WeakMap keyed by ctx) — nothing here is persisted, and the
 * ship layer reads it exactly like any other position-derived envelope.
 */
const envelopeStates = new WeakMap();

export function corridorMultiplier(ctx, position, dt) {
  let state = typeof ctx === 'object' && ctx !== null ? envelopeStates.get(ctx) : undefined;
  if (!state) {
    state = { mult: 1 };
    if (typeof ctx === 'object' && ctx !== null) envelopeStates.set(ctx, state);
  }
  let target = 1;
  try {
    const def = ctx && ctx.world && typeof ctx.world.currentSystem === 'string'
      ? SYSTEMS[ctx.world.currentSystem]
      : null;
    if (def && position && fin(position.x) && fin(position.y) && fin(position.z)
      && corridorAt(def, position.x, position.y, position.z)) {
      target = CORRIDOR_FACTOR;
    }
  } catch {
    target = 1;
  }
  // Linear ramp-in (~0.2 s to full factor) and a linear ~1 s decay on exit,
  // so the boost is felt immediately and never lingers past the corridor.
  const step = fin(dt) && dt > 0 ? Math.min(dt, 0.1) : 0;
  if (step > 0) {
    if (target > state.mult) state.mult = Math.min(target, state.mult + CORRIDOR_RAMP_RATE * step);
    // Decay rate spans the whole boost, so a full-factor exit settles back to
    // 1 in exactly CORRIDOR_DECAY_SECONDS (a partial boost settles faster).
    else state.mult = Math.max(target, state.mult - step * (CORRIDOR_FACTOR - 1) / CORRIDOR_DECAY_SECONDS);
  }
  return state.mult;
}

/** Sustained corridor speed for a hull class (its burn envelope × factor). */
export function corridorSustainedSpeed(classKey) {
  const cls = Object.prototype.hasOwnProperty.call(SHIP_CLASSES, classKey)
    ? SHIP_CLASSES[classKey]
    : SHIP_CLASSES.light;
  return cls.burn * CORRIDOR_FACTOR;
}

/**
 * Longest lane leg in the system. Region-to-region legs are chained through
 * region centers, so the raw leg bound is the max lane length (<= 8,000 u).
 */
export function maxLaneLength(def) {
  let max = 0;
  const lanes = lanesOf(def);
  for (let i = 0; i < lanes.length; i++) {
    const pts = lanePoints(def, lanes[i]);
    if (!pts) continue;
    const d = Math.hypot(pts.b[0] - pts.a[0], pts.b[1] - pts.a[1], pts.b[2] - pts.a[2]);
    if (d > max) max = d;
  }
  return max;
}

/**
 * Worst-case region-to-region leg time at corridor speed for the slowest
 * hull class. Lanes form a chain core -> r1 -> r2 -> ..., so a hop between
 * adjacent anchors is one lane; the pin divides the max lane length by the
 * freighter's sustained corridor speed (design bound: <= 20 s).
 */
export function maxRegionLegSecondsSlowest(def) {
  return maxLaneLength(def) / corridorSustainedSpeed('freighter');
}

/**
 * Worst-case station -> farthest region time along the lane chain at
 * corridor speed for the LIGHT hull (the class the existing <= 60 s pins
 * use). Lane chains are trees rooted at 'core', so BFS over lanes gives the
 * chain distance to every region.
 */
export function stationToFarthestRegionSeconds(def) {
  const lanes = lanesOf(def);
  if (!lanes.length) return 0;
  const adj = new Map();
  for (const lane of lanes) {
    if (!lane || typeof lane.from !== 'string' || typeof lane.to !== 'string') continue;
    if (!adj.has(lane.from)) adj.set(lane.from, []);
    if (!adj.has(lane.to)) adj.set(lane.to, []);
    adj.get(lane.from).push(lane.to);
    adj.get(lane.to).push(lane.from);
  }
  const pts = new Map();
  for (const id of adj.keys()) {
    const anchor = laneAnchor(def, id);
    if (anchor) pts.set(id, anchor);
  }
  if (!pts.has(CORE_ANCHOR)) return 0;
  const dist = new Map([[CORE_ANCHOR, 0]]);
  const queue = [CORE_ANCHOR];
  while (queue.length) {
    const id = queue.shift();
    const here = pts.get(id);
    for (const next of adj.get(id) ?? []) {
      if (dist.has(next)) continue;
      const there = pts.get(next);
      const step = here && there
        ? Math.hypot(there[0] - here[0], there[1] - here[1], there[2] - here[2])
        : 0;
      dist.set(next, dist.get(id) + step);
      queue.push(next);
    }
  }
  let maxChain = 0;
  for (const region of regionsOf(def)) {
    const d = dist.get(region && region.id);
    if (fin(d) && d > maxChain) maxChain = d;
  }
  return maxChain / corridorSustainedSpeed('light');
}

/**
 * Validate one system's region/lanes data against the P5b invariants.
 * `furniture` is the list of pre-P5b anchor positions ([x,y,z] arrays:
 * station, hub, gates, landmarks, clues, field center, scenery centers) the
 * regions must stay REGION_SEPARATION clear of. Returns an array of error
 * strings (empty when the data is valid); used by the focused suite for the
 * authored systems and mirrored inside the generator's validate().
 */
export function validateRegionData(def, furniture) {
  const errors = [];
  const id = (def && def.id) || '?';
  const regions = regionsOf(def);
  if (regions.length < 1 || regions.length > 3) {
    errors.push(id + ': region count ' + regions.length + ' outside 1-3');
    return errors;
  }
  const seenIds = new Set();
  const centers = [];
  for (let i = 0; i < regions.length; i++) {
    const r = regions[i];
    if (!r || typeof r !== 'object') {
      errors.push(id + ': region ' + i + ' is not an object');
      continue;
    }
    if (r.id !== id + '_r' + (i + 1)) errors.push(id + ': region id ' + r.id + ' != ' + id + '_r' + (i + 1));
    if (seenIds.has(r.id)) errors.push(id + ': duplicate region id ' + r.id);
    seenIds.add(r.id);
    if (typeof r.name !== 'string' || r.name.length === 0) errors.push(id + ': region ' + r.id + ' missing name');
    if (!REGION_KINDS.includes(r.kind)) errors.push(id + ': region ' + r.id + ' kind invalid: ' + r.kind);
    const c = r.center;
    if (!Array.isArray(c) || c.length !== 3 || !c.every(fin)) {
      errors.push(id + ': region ' + r.id + ' center malformed');
      continue;
    }
    const radial = Math.hypot(c[0], c[2]);
    if (radial < REGION_MIN_CENTER_RADIUS || radial > REGION_MAX_CENTER_RADIUS) {
      errors.push(id + ': region ' + r.id + ' center radius ' + Math.round(radial) + ' outside 3500-8000');
    }
    if (!fin(r.radius) || r.radius < REGION_MIN_RADIUS || r.radius > REGION_MAX_RADIUS) {
      errors.push(id + ': region ' + r.id + ' radius ' + r.radius + ' outside ' + REGION_MIN_RADIUS + '-' + REGION_MAX_RADIUS);
    }
    centers.push({ id: r.id, c });
  }
  for (let i = 0; i < centers.length; i++) {
    for (let j = i + 1; j < centers.length; j++) {
      const d = Math.hypot(
        centers[i].c[0] - centers[j].c[0],
        centers[i].c[1] - centers[j].c[1],
        centers[i].c[2] - centers[j].c[2],
      );
      if (d < REGION_SEPARATION) {
        errors.push(id + ': regions ' + centers[i].id + '/' + centers[j].id + ' only ' + Math.round(d) + 'u apart');
      }
    }
  }
  if (Array.isArray(furniture)) {
    for (const center of centers) {
      for (let f = 0; f < furniture.length; f++) {
        const p = furniture[f];
        if (!Array.isArray(p) || p.length !== 3 || !p.every(fin)) continue;
        const d = Math.hypot(
          center.c[0] - p[0], center.c[1] - p[1], center.c[2] - p[2],
        );
        if (d < REGION_SEPARATION) {
          errors.push(id + ': region ' + center.id + ' only ' + Math.round(d) + 'u from furniture[' + f + ']');
        }
      }
    }
  }
  const laneIds = new Set([CORE_ANCHOR, ...seenIds]);
  const seenLanes = new Set();
  for (const lane of lanesOf(def)) {
    if (!lane || typeof lane.from !== 'string' || typeof lane.to !== 'string') {
      errors.push(id + ': malformed lane record');
      continue;
    }
    const key = [lane.from, lane.to].sort().join('|');
    if (seenLanes.has(key)) errors.push(id + ': duplicate lane ' + key);
    seenLanes.add(key);
    if (lane.from === lane.to) errors.push(id + ': self lane ' + lane.from);
    for (const end of [lane.from, lane.to]) {
      if (!laneIds.has(end)) errors.push(id + ': lane endpoint unknown: ' + end);
    }
    if (!laneAnchor(def, lane.from) || !laneAnchor(def, lane.to)) {
      errors.push(id + ': lane ' + key + ' endpoint does not resolve');
    }
  }
  return errors;
}

/** Collect the pre-P5b furniture anchors of a system def for validateRegionData. */
export function furnitureAnchors(def) {
  if (!def) return [];
  const out = [];
  const push = (p) => {
    if (Array.isArray(p) && p.length === 3 && p.every(fin)) out.push(p);
  };
  if (def.station) push(def.station.position);
  if (def.hub) push(def.hub.position);
  if (def.field) push(def.field.center);
  for (const g of def.gates ?? []) push(g && g.position);
  for (const lm of def.landmarks ?? []) push(lm && lm.position);
  for (const cl of def.clues ?? []) push(cl && cl.position);
  return out;
}
